-- fab_ops seed: one recorded SMT2020 run (scripts/export_fab_ops_sql.py).
-- run_id=resilimes-s1-12h-baseline seed=1 hours=12 policy=resilimes
-- Routed to database fab_ops / datasource fab_ops by scripts/zetaris_setup.sh.
CREATE TABLE resilimes.ops_events (run_id TEXT, seq INTEGER, t_sec DOUBLE PRECISION, kind TEXT, tool TEXT, lot_id TEXT, step INTEGER, family TEXT, detail TEXT);
CREATE TABLE resilimes.ops_ai_decisions (run_id TEXT, seq INTEGER, t_sec DOUBLE PRECISION, source TEXT, tool TEXT, lead_lot TEXT, displaced_lot TEXT, detail TEXT);
CREATE TABLE resilimes.ops_kpi_hourly (run_id TEXT, hour INTEGER, family TEXT, wip_waiting INTEGER, arrivals INTEGER, lot_starts INTEGER, busy_tool_h DOUBLE PRECISION, down_tool_h DOUBLE PRECISION, pm_tool_h DOUBLE PRECISION, setup_min DOUBLE PRECISION);
